import type { SystemSettings } from '../shared/settings'
import type { AddResult, BoardPage } from '../shared/types'

export interface ClipperConnection {
  origin: string
  token: string
}

/** Parses a connection code generated by the self-hosted settings page (`https://host/#bm_...`) */
export function parseConnectionCode(raw: string): ClipperConnection | null {
  const trimmed = raw.trim()
  if (!trimmed) return null
  let parsed: URL
  try {
    parsed = new URL(trimmed)
  } catch {
    return null
  }
  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') return null
  const token = parsed.hash.replace(/^#/, '').trim()
  if (!token) return null
  return { origin: parsed.origin, token }
}

export type ClipperMethodMap = {
  board: [desktopId?: number]
  settings: []
  addBookmark: [url: string, desktopId?: number, groupId?: number, title?: string]
}

export type ClipperResultMap = {
  board: BoardPage
  settings: SystemSettings
  addBookmark: AddResult
}

/** Sends a token-authenticated RPC call to the self-hosted server */
export async function clipperRpc<M extends keyof ClipperMethodMap>(
  connection: ClipperConnection,
  method: M,
  ...args: ClipperMethodMap[M]
): Promise<ClipperResultMap[M]> {
  let response: Response
  try {
    response = await fetch(`${connection.origin}/api/rpc`, {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        authorization: `Bearer ${connection.token}`,
      },
      body: JSON.stringify({ method, args }),
    })
  } catch {
    throw new Error('无法连接服务器，请检查地址和网络')
  }
  const data = await response.json().catch(() => null) as { value?: ClipperResultMap[M]; error?: string } | null
  if (response.status === 401) throw new Error(data?.error ?? '连接码已失效，请在扩展设置里重新填入')
  if (!response.ok) throw new Error(data?.error ?? `请求失败（HTTP ${response.status}）`)
  return data?.value as ClipperResultMap[M]
}
